#!/usr/bin/env python3
from pathlib import Path
root = Path(__file__).resolve().parents[2]
checks = []
def check(name, ok): checks.append((name, bool(ok)))
startup = (root/'Sources/Environment/Helper/Runtime/HelperStartupRecoveryCheck.swift').read_text()
executor = (root/'Sources/Environment/Helper/Execution/HelperThreeFileTransaction.swift').read_text()
store = (root/'Sources/Environment/Helper/Execution/HelperDeploymentDurableLedgerStore.swift').read_text()
ledger = (root/'Sources/Environment/Helper/Execution/HelperDeploymentIdempotencyLedger.swift').read_text()
dispatch = (root/'Sources/Environment/Helper/Runtime/HelperRequestDispatcher.swift').read_text()
backend = (root/'Sources/Environment/Helper/Execution/HelperProductionDeploymentBackend.swift').read_text()
smoke = (root/'Build/Scripts/p2-25-authorized-recovery-smoke.swift').read_text()
check('recovery capability requires explicit operator confirmation', 'guard operatorConfirmed' in startup and 'confirmationRequired' in startup)
check('recovery capability accepts only an unprivileged App peer', 'context.peer.uid != 0' in startup and 'context.identity.uid != 0' in startup)
check('recovery capability binds socket credentials to authenticated identity', 'context.peer.pid == context.identity.pid' in startup and 'context.peer.gid == context.identity.gid' in startup)
check('recovery capability requires audit-token and pid-generation evidence', 'hasCompleteDarwinProcessGenerationEvidence(context.identity)' in startup)
check('recovery authorization is time-bounded', 'authorizationExpired' in startup and 'authorizedAt' in startup and 'clockSkewLimit' in startup)
check('recovery writes an accepted audit event before mutation', 'transaction_recovery_started' in startup and startup.index('transaction_recovery_started') < startup.index('executor.reconcile(expectedTransactionID'))
check('recovery writes a completion audit event', 'transaction_recovery_committed' in startup and 'transaction_recovery_rolled_back' in startup)
check('authorization is transaction-scoped', 'evidence.transactionID == authorization.transactionID' in startup)
check('recovery requires durable ledger and immutable binding match', 'ledgerStore.load()' in startup and 'HelperDeploymentJournalReconciliation.compare' in startup)
check('executor checks expected transaction ID before mutation', 'journal.transactionID == expectedTransactionID' in executor)
check('filesystem recovery preserves journal until ledger finalization', 'preserveJournal: true' in startup and 'clearReconciledJournal' in startup)
check('ledger finalization occurs before journal clear', startup.index('ledgerStore.finalizeRecovered') < startup.index('executor.clearReconciledJournal'))
check('journal clear rechecks destination and auxiliary hashes', 'func clearReconciledJournal' in executor and 'hashIfPresent(fd, journal.backupDylib) == nil' in executor and 'hashIfPresent(fd, journal.tempManifest) == nil' in executor)
check('ledger finalization is bound to batch transaction and request IDs', 'record.transactionID == binding.transactionID' in store and 'Set(record.requestIDs) == Set(binding.requestIDs)' in store)
check('rolled-back terminal state blocks batch replay', 'case .rolledBack' in ledger and 'deploymentBatchRolledBack' in dispatch)
check('startup inspection remains read-only', '.reconcile(' not in startup.split('/// Short-lived capability')[0])
check('production execution gates remain closed', 'static let executionReleased = false' in dispatch and 'static let executionReleased = false' in backend)
check('host smoke covers rollback commit and crash-window retry', 'simulate a process crash' in smoke.lower() and 'expectedLedger: .rolledBack' in smoke and 'expectedLedger: .completed' in smoke)
for name, ok in checks:
    print(('PASS' if ok else 'FAIL') + ' ' + name)
print(f'{sum(v for _, v in checks)}/{len(checks)} passed')
raise SystemExit(0 if all(v for _, v in checks) else 1)
